SELECT 'gongkao', '条件关系', 'kp-xc-analogy-int-condition', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"条件关系"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"A 的发生是 B 的前提。区分充分条件（有 A 必有 B）和必要条件（没 A 必没 B）。约 88 题。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「只要 A 就 B」→ 充分条件"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「只有 A 才 B」→ 必要条件"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"「如果 A 那么 B」→ 充分条件"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"充分条件和必要条件不能颠倒：「只要下雨地就湿」不能反过来说「只要地湿就下雨」"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"因果关系和条件关系的区别：因果是「A 导致 B」，条件是「A 是 B 的前提」"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"条件关系考频中等，关键是区分充分条件和必要条件，以及和因果关系的区别。"}]}]}]}]}$$ AS jsonb), NULL, '类比推理-内涵关系-条件关系：充分条件与必要条件的区分。', category_node.id, CAST('["类比推理", "内涵关系", "条件关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_logical_condition", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
